import re
from datetime import datetime


def extract(text: str) -> dict:
    person_match = re.search(r'Appointment\s+confirmed\s+for\s+(.+?)\s+with\s+Dr\.', text, re.IGNORECASE)
    if not person_match:
        raise ValueError('Missing appointment confirmation label')
    person = person_match.group(1).strip()

    date_match = re.search(r'^[ \t]*Date:[ \t]*([^\n\r]+)', text, re.IGNORECASE | re.MULTILINE)
    if not date_match:
        raise ValueError('Missing Date label')
    date_str = date_match.group(1).strip()

    time_match = re.search(r'^[ \t]*Time:[ \t]*([^\n\r]+)', text, re.IGNORECASE | re.MULTILINE)
    if not time_match:
        raise ValueError('Missing Time label')
    time_str = time_match.group(1).strip()

    try:
        due_date = datetime.strptime(date_str, '%A, %d %B %Y').strftime('%Y-%m-%d')
    except ValueError:
        try:
            due_date = datetime.strptime(date_str, '%A, %d %b %Y').strftime('%Y-%m-%d')
        except ValueError as e:
            raise ValueError('Unparseable appointment date') from e

    time_norm = re.sub(r'\s+', ' ', time_str.upper())
    try:
        event_time = datetime.strptime(time_norm, '%I:%M %p').strftime('%H:%M')
    except ValueError as e:
        raise ValueError('Unparseable appointment time') from e

    return {
        'type': 'meeting',
        'provider': 'Apollo Clinic',
        'currency': 'INR',
        'due_date': due_date,
        'event_time': event_time,
        'person': person,
    }
